<?php require_once __DIR__.'/config/auth.php';$user=require_admin();if($_SERVER['REQUEST_METHOD']!=='POST')redirect('archive_list.php');verify_csrf();$id=(int)($_POST['id']??0);$pdo=db();$s=$pdo->prepare('SELECT * FROM archives WHERE id=?');$s->execute([$id]);$a=$s->fetch();if(!$a){flash('error','Archive not found.');redirect('archive_list.php');}$s=$pdo->prepare('SELECT file_path FROM archive_documents WHERE archive_id=? UNION ALL SELECT image FROM witnesses WHERE archive_id=?');$s->execute([$id,$id]);$files=$s->fetchAll(PDO::FETCH_COLUMN);foreach(['seller_image','buyer_image','id_card_file','moj_document_file'] as $field)if(!empty($a[$field]))$files[]=$a[$field];$s=$pdo->prepare('DELETE FROM archives WHERE id=?');$s->execute([$id]);foreach(array_unique(array_filter($files)) as $f)remove_file($f);log_activity('archive deleted','archive',$id,$a['ref_number']??null,'Archive deleted',$user);flash('success','Archive deleted.');redirect('archive_list.php');